static
void kernel_covariance(int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;
  const DATA_TYPE inv_n = (DATA_TYPE)(1.0 / float_n);

#pragma scop
  for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      int i = 0;
      for (; i < _PB_N; ++i)
        sum += data[i][j];
      mean[j] = sum * inv_n;
    }

  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE* row = data[i];
      int j = 0;
      for (; j < _PB_M; ++j)
        row[j] -= mean[j];
    }

  for (i = 0; i < _PB_M; i++)
    for (j = i; j < _PB_M; j++)
      {
        DATA_TYPE sum = SCALAR_VAL(0.0);
        int k = 0;
        for (; k < _PB_N; ++k)
          sum += data[k][i] * data[k][j];
        cov[i][j] = sum * inv_n;
        cov[j][i] = cov[i][j];
      }
#pragma endscop
}

