    for (k = 0; k < _PB_M; k++) {
      const DATA_TYPE aik = ai[k];
      const DATA_TYPE a_k = A[0][k];
      (void)a_k;

      j = 0;
      for (; j <= i; ++j) {
        ci[j] += alpha * aik * A[j][k];
      }
    }
  }
#pragma endscop
}

#include <riscv_vector.h>

static
void kernel_trisolv(int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      x[i] = b[i];
      for (j = 0; j < i; j++)
        x[i] -= L[i][j] * x[j];
      x[i] = x[i] / L[i][i];
    }
#pragma endscop
}

#include <riscv_vector.h>

static
void kernel_trmm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_M; i++) {
    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE sum = B[i][j];
      for (k = i + 1; k < _PB_M; k++) {
        sum += A[k][i] * B[k][j];
      }
      B[i][j] = alpha * sum;
    }
  }
#pragma endscop
}
